package com.pranit.productsupport.core.service;
import com.pranit.productsupport.contracts.*; import com.pranit.productsupport.core.domain.*; import com.pranit.productsupport.core.repository.*; import java.time.Instant; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class TicketTransactionService {
 private final AppUserRepository users;private final OrderItemRepository items;private final TicketRepository tickets;private final IdempotencyKeyRepository keys;private final TicketStatusHistoryRepository history;private final OutboxService outbox;
 public TicketTransactionService(AppUserRepository u,OrderItemRepository i,TicketRepository t,IdempotencyKeyRepository k,TicketStatusHistoryRepository h,OutboxService o){users=u;items=i;tickets=t;keys=k;history=h;outbox=o;}
 @Transactional public TicketResponse create(Long userId,String key,CreateTicketRequest req){String hash=RequestHash.ticket(userId,req);var existing=keys.findByUser_IdAndKey(userId,key);if(existing.isPresent()){IdempotencyKey old=existing.get();if(!old.getRequestHash().equals(hash))throw ApiException.conflict("Idempotency-Key was already used with a different request body");if(old.getTicket()==null)throw ApiException.conflict("An identical request is still processing; retry shortly");return dto(old.getTicket());}
  AppUser customer=users.findById(userId).orElseThrow(()->ApiException.notFound("Customer not found"));OrderItem item=items.findById(req.orderItemId()).orElseThrow(()->ApiException.notFound("Eligible purchased item not found"));if(!item.getOrder().getCustomer().getId().equals(userId))throw ApiException.notFound("Eligible purchased item not found");if(item.getOrder().getStatus()!=OrderStatus.DELIVERED)throw new ApiException(HttpStatus.CONFLICT,"A defect ticket can only be raised for a delivered purchase");
  IdempotencyKey idem=keys.saveAndFlush(new IdempotencyKey(customer,key,hash));Ticket ticket=tickets.save(new Ticket(customer,item,req.issueDescription().trim(),req.priority()));history.save(new TicketStatusHistory(ticket,null,TicketStatus.OPEN,customer,"Customer submitted a product defect report"));idem.complete(ticket);outbox.enqueue("TicketCreated",ticket.getId().toString(),new TicketCreatedEvent(ticket.getId(),customer.getId(),item.getId(),item.getProduct().getId(),item.getProduct().getName(),ticket.getIssueDescription(),Instant.now()));return dto(ticket);
 }
 @Transactional(readOnly=true) public TicketResponse findResponseById(Long id){Ticket t=tickets.findById(id).orElseThrow(()->ApiException.notFound("Ticket not found"));return dto(t);}
 public TicketResponse dto(Ticket t){return new TicketResponse(t.getId(),t.getCustomer().getId(),t.getOrderItem().getId(),t.getOrderItem().getProduct().getId(),t.getOrderItem().getProduct().getName(),t.getIssueDescription(),t.getStatus(),t.getPriority(),t.getAssignedTo()==null?null:t.getAssignedTo().getId(),t.getCreatedAt(),t.getUpdatedAt(),t.getVersion());}
}
